# -*- coding: utf-8 -*-
SVGS = ['<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="28" text-anchor="middle" font-size="15" font-weight="bold" fill="#0f172a">EXPRESSING PAST HABITS AND STATES: USED TO vs. WOULD</text>\n  <rect x="25" y="50" width="315" height="190" rx="10" fill="#dbeafe" stroke="#2563eb" stroke-width="2"/>\n  <text x="182" y="75" text-anchor="middle" font-size="13" font-weight="bold" fill="#1e40af">USED TO + V1 (Habits &amp; States)</text>\n  <text x="40" y="100" font-size="11" font-weight="bold" fill="#1d4ed8">• (+) Subject + used to + V1</text>\n  <text x="48" y="116" font-size="10.5" fill="#334155">She used to live in a small cottage.</text>\n  <text x="40" y="138" font-size="11" font-weight="bold" fill="#1d4ed8">• (-) Subject + didn\'t use to + V1</text>\n  <text x="48" y="154" font-size="10.5" fill="#334155">People didn\'t use to have smartphones.</text>\n  <text x="40" y="176" font-size="11" font-weight="bold" fill="#1d4ed8">• (?) Did + Subject + use to + V1?</text>\n  <text x="48" y="192" font-size="10.5" fill="#334155">Did you use to play marbles as a child?</text>\n  <text x="40" y="218" font-size="10.5" font-weight="bold" fill="#1e40af">* Hem hareket (action) hem durum (state) fiilleriyle!</text>\n\n  <rect x="360" y="50" width="315" height="190" rx="10" fill="#fef3c7" stroke="#d97706" stroke-width="2"/>\n  <text x="517" y="75" text-anchor="middle" font-size="13" font-weight="bold" fill="#92400e">WOULD + V1 (Repeated Past Actions)</text>\n  <rect x="378" y="90" width="280" height="65" rx="6" fill="#ffffff" stroke="#f59e0b" stroke-width="1.5"/>\n  <text x="517" y="110" text-anchor="middle" font-size="11" font-weight="bold" fill="#b45309">Kullanım Alanı: Tekrarlanan Eylemler</text>\n  <text x="517" y="128" text-anchor="middle" font-size="10.5" fill="#334155">Every winter, my grandma would knit</text>\n  <text x="517" y="144" text-anchor="middle" font-size="10.5" fill="#334155">warm wool socks for all of us.</text>\n  <rect x="378" y="165" width="280" height="62" rx="6" fill="#fee2e2" stroke="#dc2626" stroke-width="1.5"/>\n  <text x="517" y="185" text-anchor="middle" font-size="11" font-weight="bold" fill="#991b1b">Önemli Kural (State Verbs):</text>\n  <text x="517" y="201" text-anchor="middle" font-size="10" fill="#7f1d1d">be, have, live, know, own gibi durum</text>\n  <text x="517" y="215" text-anchor="middle" font-size="10" font-weight="bold" fill="#991b1b">fiilleriyle \'would\' KULLANILMAZ!</text>\n</svg>', '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="28" text-anchor="middle" font-size="15" font-weight="bold" fill="#0f172a">NARRATIVE TENSES: PAST CONTINUOUS &amp; SIMPLE PAST</text>\n  <rect x="20" y="50" width="210" height="190" rx="8" fill="#ede9fe" stroke="#7c3aed" stroke-width="1.8"/>\n  <text x="125" y="74" text-anchor="middle" font-size="12" font-weight="bold" fill="#5b21b6">1. WHEN + Simple Past</text>\n  <text x="30" y="98" font-size="10.5" font-weight="bold" fill="#6d28d9">When + V2, was/were + V-ing</text>\n  <text x="30" y="120" font-size="10" fill="#334155">• Kısa eylem uzun eylemi böler:</text>\n  <text x="30" y="140" font-size="10" fill="#475569">\'When the earthquake struck,</text>\n  <text x="30" y="156" font-size="10" fill="#475569">people were sleeping in their</text>\n  <text x="30" y="172" font-size="10" fill="#475569">houses.\'</text>\n  <text x="30" y="198" font-size="10" font-weight="bold" fill="#5b21b6">• When + V2, V2 (Arka arkaya):</text>\n  <text x="30" y="214" font-size="9.5" fill="#334155">When the rain stopped, we left.</text>\n\n  <rect x="245" y="50" width="210" height="190" rx="8" fill="#dcfce7" stroke="#16a34a" stroke-width="1.8"/>\n  <text x="350" y="74" text-anchor="middle" font-size="12" font-weight="bold" fill="#15803d">2. WHILE / AS + Past Cont.</text>\n  <text x="255" y="98" font-size="10.5" font-weight="bold" fill="#166534">While + was/were V-ing, V2</text>\n  <text x="255" y="120" font-size="10" fill="#334155">• Devam eden süreç vurgulanır:</text>\n  <text x="255" y="140" font-size="10" fill="#475569">\'While they were crossing the</text>\n  <text x="255" y="156" font-size="10" fill="#475569">mountain pass, the engine broke</text>\n  <text x="255" y="172" font-size="10" fill="#475569">down in the snow.\'</text>\n  <text x="255" y="198" font-size="10" font-weight="bold" fill="#15803d">• As = While (Süreç bağlacı)</text>\n\n  <rect x="470" y="50" width="210" height="190" rx="8" fill="#e0f2fe" stroke="#0284c7" stroke-width="1.8"/>\n  <text x="575" y="74" text-anchor="middle" font-size="12" font-weight="bold" fill="#0369a1">3. Eş Zamanlı İki Süreç</text>\n  <text x="480" y="98" font-size="10.5" font-weight="bold" fill="#075985">While + Past Cont., Past Cont.</text>\n  <text x="480" y="120" font-size="10" fill="#334155">• İki uzun eylem aynı anda sürer:</text>\n  <text x="480" y="140" font-size="10" fill="#475569">\'While the volunteers were</text>\n  <text x="480" y="156" font-size="10" fill="#475569">setting up tents, the doctors</text>\n  <text x="480" y="172" font-size="10" fill="#475569">were treating the injured.\'</text>\n  <text x="480" y="198" font-size="10" font-weight="bold" fill="#0369a1">• Birbirini kesmeyen eylemler!</text>\n</svg>', '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="28" text-anchor="middle" font-size="15" font-weight="bold" fill="#0f172a">THEME 3 VOCABULARY &amp; NARRATIVE SEQUENCING CONNECTORS</text>\n  <rect x="25" y="50" width="315" height="190" rx="10" fill="#fef2f2" stroke="#dc2626" stroke-width="2"/>\n  <text x="182" y="75" text-anchor="middle" font-size="13" font-weight="bold" fill="#991b1b">Key Vocabulary: Hard Times</text>\n  <text x="40" y="100" font-size="10.5" fill="#334155">• hardship / adversity: zorluk, güçlük</text>\n  <text x="40" y="120" font-size="10.5" fill="#334155">• poverty / scarcity: yoksulluk / kıtlık</text>\n  <text x="40" y="140" font-size="10.5" fill="#334155">• make ends meet: kıt kanaat geçinmek</text>\n  <text x="40" y="160" font-size="10.5" fill="#334155">• hit rock bottom: dibe vurmak</text>\n  <text x="40" y="180" font-size="10.5" font-weight="bold" fill="#b91c1c">• overcome / get through: üstesinden gelmek</text>\n  <text x="40" y="200" font-size="10.5" font-weight="bold" fill="#b91c1c">• resilience / perseverance: yılmazlık, azim</text>\n  <text x="40" y="220" font-size="10.5" fill="#334155">• turn over a new leaf: yeni bir sayfa açmak</text>\n\n  <rect x="360" y="50" width="315" height="190" rx="10" fill="#eff6ff" stroke="#2563eb" stroke-width="2"/>\n  <text x="517" y="75" text-anchor="middle" font-size="13" font-weight="bold" fill="#1e40af">Narrative Time Linkers (Sıralama)</text>\n  <text x="375" y="102" font-size="11" font-weight="bold" fill="#1d4ed8">1. Beginning (Başlangıç):</text>\n  <text x="383" y="118" font-size="10.5" fill="#334155">At first, Initially, In the beginning, First of all</text>\n  <text x="375" y="144" font-size="11" font-weight="bold" fill="#1d4ed8">2. Middle &amp; Sudden Events (Gelişme):</text>\n  <text x="383" y="160" font-size="10.5" fill="#334155">Then, Next, Afterwards, Meanwhile, Suddenly</text>\n  <text x="375" y="186" font-size="11" font-weight="bold" fill="#1d4ed8">3. Ending (Sonuç):</text>\n  <text x="383" y="202" font-size="10.5" fill="#334155">Eventually, Finally, In the end, At last</text>\n</svg>']

def uygula(v):
    for i, b in enumerate(v.get('bolumler', [])):
        if i < len(SVGS):
            b['gorsel'] = SVGS[i]
